const items = $input.all();
const results = [];
for (const item of items) {
  const text = item.json.message?.text || '';
  const chatId = item.json.message?.chat?.id;
  const username = item.json.message?.from?.username || 'user';

  // Parse: /invoice <client>
  // Then items line by line: <item> <price>
  const lines = text.split('\n');
  const firstLine = lines[0].trim();

  if (firstLine.startsWith('/invoice')) {
    const clientName = firstLine.replace('/invoice', '').trim() || 'Client';
    const invoiceItems = [];
    let total = 0;

    for (let i = 1; i < lines.length; i++) {
      const match = lines[i].trim().match(/^(.+?)\s+(\d+)$/);
      if (match) {
        const itemName = match[1].trim();
        const price = parseInt(match[2]);
        invoiceItems.push({ name: itemName, price });
        total += price;
      }
    }

    const invoiceNumber = `INV-${Date.now().toString(36).toUpperCase()}`;
    results.push({
      json: {
        command: 'invoice',
        invoiceNumber,
        clientName,
        items: invoiceItems,
        itemCount: invoiceItems.length,
        subtotal: total,
        tax: Math.round(total * 0.11),
        total: total + Math.round(total * 0.11),
        chatId,
        username,
        date: new Date().toISOString().split('T')[0],
        timestamp: new Date().toISOString()
      }
    });
  } else {
    results.push({
      json: {
        command: 'help',
        chatId
      }
    });
  }
}
return results;

const items = $input.all();
const inv = items[0].json;
let text = `📄 <b>INVOICE</b>\n`;
text += `━━━━━━━━━━━━━━━━━━\n`;
text += `📋 No: ${inv.invoiceNumber}\n`;
text += `📅 Date: ${inv.date}\n`;
text += `👤 Client: ${inv.clientName}\n`;
text += `━━━━━━━━━━━━━━━━━━\n\n`;

const invoiceItems = Array.isArray(inv.items) ? inv.items : JSON.parse(inv.items || '[]');
invoiceItems.forEach((item, idx) => {
  text += `${idx + 1}. ${item.name}\n   Rp ${item.price.toLocaleString()}\n`;
});

text += `\n━━━━━━━━━━━━━━━━━━\n`;
text += `Subtotal: Rp ${inv.subtotal.toLocaleString()}\n`;
text += `Tax (11%): Rp ${inv.tax.toLocaleString()}\n`;
text += `<b>TOTAL: Rp ${inv.total.toLocaleString()}</b>\n`;
text += `━━━━━━━━━━━━━━━━━━\n`;
text += `\nGenerated by Invoice Bot 🤖`;

return [{ json: { text, chatId: inv.chatId, ...inv } }];
